;(function(){
  function loadNotices(root){
    if(!root) return;
    function mount(){
      var mod = window.XmModules && window.XmModules["/notices"];
      if(!mod || typeof mod.mount !== "function") return;
      if(typeof root.__xmNoticeUnmount === "function"){
        try{ root.__xmNoticeUnmount(); }catch(e){}
      }
      root.__xmNoticeUnmount = mod.mount(root);
    }
    if(window.XmModules && window.XmModules["/notices"] && typeof window.XmModules["/notices"].mount === "function"){
      mount();
      return;
    }
    var src = "/shared/modules/notices.js";
    var s = document.querySelector('script[src^="'+src+'"]');
    if(!s){
      s = document.createElement("script");
      s.src = src;
      s.onload = function(){ s.setAttribute("data-xm-loaded","1"); mount(); };
      document.head.appendChild(s);
      return;
    }
    s.addEventListener("load", mount);
    if(s.getAttribute("data-xm-loaded")==="1") mount();
  }
  window.__xmMountOrgNotices = function(){
    loadNotices(document.getElementById("org-notices-root"));
  };
})();
